func (_c *BlueprintCreateBulk) OnConflictColumns(columns ...string) *BlueprintUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &BlueprintUpsertBulk{
		create: _c,
	}
}

